Commit:     Yury Ivanovich <Yury.Ivanovich@linuxmail.org>
CommitDate: Fri Nov 14 10:23:30 2025 +0000

    Bug 1999677 - Don't show Gmail's "All Mail" folder as "Archives" in the folder pane. r=Yury.Ivanovich,tobyp

    Differential Revision: https://phabricator.services.mozilla.com/D272310

diff --git a/mailnews/base/public/nsMsgFolderFlags.idl b/mailnews/base/public/nsMsgFolderFlags.idl
index a36fe002e46..9b82a3c0cdf 100644
--- a/mailnews/base/public/nsMsgFolderFlags.idl
+++ b/mailnews/base/public/nsMsgFolderFlags.idl
@@ -71,12 +71,12 @@ interface nsMsgFolderFlags : nsISupports {
   const nsMsgFolderFlagType Queue           = 0x00000800;
   /// Whether this is the primary inbox folder.
   const nsMsgFolderFlagType Inbox           = 0x00001000;
-  /// Whether this folder on online IMAP
+  /// Whether this folder is an online IMAP folder.
   const nsMsgFolderFlagType ImapBox         = 0x00002000;
-  /// Whether this is an archive folder
+  /// Whether this is an archive folder.
   const nsMsgFolderFlagType Archive         = 0x00004000;
-  /// This used to be used for virtual newsgroups
-  const nsMsgFolderFlagType Unused1         = 0x00008000;
+  /// Whether this is the Gmail "All Mail" folder.
+  const nsMsgFolderFlagType AllMail         = 0x00008000;
   /// Used to be for categories
   const nsMsgFolderFlagType Unused4         = 0x00010000;
   /// Used to be for new msgs in a folder
diff --git a/mailnews/base/src/nsMsgDBFolder.cpp b/mailnews/base/src/nsMsgDBFolder.cpp
index a7b46b1f0b4..7449ca42bf4 100644
--- a/mailnews/base/src/nsMsgDBFolder.cpp
+++ b/mailnews/base/src/nsMsgDBFolder.cpp
@@ -3058,7 +3058,8 @@ nsString nsMsgDBFolder::GetLocalizedNameInternal() {
   if (mFlags & nsMsgFolderFlags::Junk) {
     return kLocalizedJunkName;
   }
-  if (mFlags & nsMsgFolderFlags::Archive) {
+  if (mFlags & nsMsgFolderFlags::Archive &&
+      !(mFlags & nsMsgFolderFlags::AllMail)) {
     return kLocalizedArchivesName;
   }
   return u""_ns;
diff --git a/mailnews/imap/src/nsImapMailFolder.cpp b/mailnews/imap/src/nsImapMailFolder.cpp
index 8369e1352b6..179002aab2e 100644
--- a/mailnews/imap/src/nsImapMailFolder.cpp
+++ b/mailnews/imap/src/nsImapMailFolder.cpp
@@ -1147,8 +1147,9 @@ NS_IMETHODIMP nsImapMailFolder::SetBoxFlags(int32_t aBoxFlags) {
     }
   }
   // Treat the GMail all mail folder as the archive folder.
-  if (m_boxFlags & (kImapAllMail | kImapArchive))
-    newFlags |= nsMsgFolderFlags::Archive;
+  if (m_boxFlags & kImapAllMail)
+    newFlags |= nsMsgFolderFlags::Archive | nsMsgFolderFlags::AllMail;
+  if (m_boxFlags & kImapArchive) newFlags |= nsMsgFolderFlags::Archive;

   SetFlags(newFlags);
   return NS_OK;
diff --git a/mailnews/imap/test/unit/test_folderNamesImap.js b/mailnews/imap/test/unit/test_folderNamesImap.js
index 9e9759545d2..40538ca9466 100644
--- a/mailnews/imap/test/unit/test_folderNamesImap.js
+++ b/mailnews/imap/test/unit/test_folderNamesImap.js
@@ -27,7 +27,8 @@ add_task(async function () {
   const l10n = new Localization(["messenger/messenger.ftl"], true);
   const spamFolderName = l10n.formatValueSync("folder-name-spam");

-  const server = new IMAPServer();
+  // Extensions needed for the \\AllMail flag.
+  const server = new IMAPServer({ extensions: ["GMAIL", "RFC3348"] });
   server.daemon.createMailbox("Trash", {
     flags: ["\\Trash"],
     subscribed: true,
@@ -42,6 +43,11 @@ add_task(async function () {
     flags: ["\\Archive"],
     subscribed: true,
   });
+  server.daemon.createMailbox("All Mail", {
+    flags: ["\\Archive"],
+    subscribed: true,
+    specialUseFlag: "\\AllMail",
+  });

   const account = MailServices.accounts.createAccount();
   account.addIdentity(MailServices.accounts.createIdentity());
@@ -93,4 +99,11 @@ add_task(async function () {
   Assert.equal(archivesFolder.name, "Archives");
   Assert.equal(archivesFolder.localizedName, archivesFolderName);
   Assert.equal(archivesFolder.msgDatabase.dBFolderInfo.folderName, "");
+
+  const allMailFolder = rootFolder.getChildNamed("All Mail");
+  Assert.ok(allMailFolder.flags & Ci.nsMsgFolderFlags.Archive);
+  Assert.ok(allMailFolder.flags & Ci.nsMsgFolderFlags.AllMail);
+  Assert.equal(allMailFolder.name, "All Mail");
+  Assert.equal(allMailFolder.localizedName, "All Mail");
+  Assert.equal(allMailFolder.msgDatabase.dBFolderInfo.folderName, "");
 });
